bool isTrackVisible(String path) {
  if (!scroll.hasClients) return false;
  if (ctrl.currentPath == null) return false;

  final tracks = ctrl.tracks;
  final index = tracks.indexWhere((t) => t.path == path);
  if (index < 0) return false;

  // File rows render as: folders (above), then tracks, then the up row
  // anchored at the list bottom.
  final hasUp = 1; // ctrl.currentPath != null
  final childIndex = hasUp + (tracks.length - 1 - index);

  final rowHeight = theme.geometry.rowHeight;
  final rowCenter = childIndex * rowHeight;
  final rowTop = rowCenter - rowHeight / 2;
  final rowBottom = rowCenter + rowHeight / 2;

  final pos = scroll.position;
  final visibleTop = pos.pixels;
  final visibleBottom = pos.pixels + pos.viewportDimension;

  // Small overscan to avoid flicker on the boundary due to rounding.
  final pad = rowHeight * 0.15;
  return rowBottom > visibleTop + pad && rowTop < visibleBottom - pad;
}

// Register the scroll-to-track + visibility probe implementations onto
// the passed handle; clear them on dispose / handle swap.
useEffect(() {
  browserController?._scrollToTrack = scrollToTrack;
  browserController?._isTrackVisible = isTrackVisible;
  browserController?._notifyVisibilityChanged();

  // Drive visibility updates for the crumb action.
  void onScroll() => browserController?._notifyVisibilityChanged();
  scroll.addListener(onScroll);

  return () {
    browserController?._scrollToTrack = null;
    browserController?._isTrackVisible = null;
    scroll.removeListener(onScroll);
  };
}, [browserController, scroll]);
